layers.vertex:
attribute vec3 aO, aS; uniform float uTime; varying vec2 vP; varying float vOn, vOff;
    void main(){ float on = uTime - aS.x, off = uTime - aS.y;
      if (aS.z < .5 || on < 0. || (off > .35 && aS.y >= aS.x)){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vOn = on; vOff = aS.y > aS.x ? off : -1.;
      vec2 w = position.xy*8.348; vP = w*0.192;
      gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(w.x, .025, -w.y), 1.); }

layers.fragment:
uniform float uTime; uniform vec3 uC, uP; varying vec2 vP; varying float vOn, vOff; float eox(float x){ return x >= 1. ? 1. : 1. - pow(2., -10.*x); }
    float line(float d, float w){ return exp(-d*d/(w*w)); }
    void main(){
      float r = length(vP), a = atan(vP.y, vP.x), rot = uTime*.05;
      float k = eox(clamp(vOn/.3, 0., 1.)), R = 1.15*mix(.35, 1., k);
      float fade = 1.; if (vOff >= 0.){ float q = clamp(vOff/.3, 0., 1.); fade = (1. - q)*(1. - q); R *= 1. + .06*q; }
      float pk = vOn < .033 ? 2.2 : 1. + .8*exp(-max(vOn - .033, 0.)*10.);
      float flow = .7 + .3*pow(.5 + .5*sin(a*3. - uTime*.6), 2.);          /* energy drifting slowly round the ring */
      float lum = (line(r - R, .007)*.75 + exp(-pow((r - R)/.04, 2.))*.12)*flow + line(r - (R - .12), .004)*.35;
      float a4 = mod(a + rot, 1.5708) - .7854;
      float rune = 0.;
      /* Sun: three small suns (the approved Sun Stance symbol: disc + rim + 4-point star rays + soft corona) riding just inside
           the ring, slowly counter-rotating - same placement as the Moon crescents */
        float a3 = mod(a - uTime*.07, 2.0944) - 1.0472; vec2 sq = (vec2(r*cos(a3) - (R - .075), r*sin(a3)))/.125;
        float sr = length(sq), sa = atan(sq.y, sq.x);
        float disc = smoothstep(.36, .32, sr), rim = exp(-pow((sr - .34)/.03, 2.));
        float star = pow(abs(cos(sa*2.)), 14.)*exp(-sr*2.4)*smoothstep(.2, .4, sr), corona = exp(-sr*sr*6.)*.25;
        rune += (disc*.45 + rim*.9 + star*.9 + corona)*smoothstep(1., .8, sr);
      float d4 = length(vec2(r*cos(a4) - R, r*sin(a4))); lum += exp(-d4*d4/.0006)*.6;   /* 4 nodes on the ring */
      float hot = line(r - R, .003)*.35*flow + rune*.35;
      lum += rune*mix(1., 1.4, 1. - k);
      /* switch pulse: a thin ring runs out past the aura and is gone in 0.25 s */
      float pr = mix(R*.4, R + .35, eox(clamp(vOn/.25, 0., 1.))), pf = vOn < .25 ? pow(1. - vOn/.25, 1.5) : 0.;
      lum += line(r - pr, .012)*pf*1.2; hot += line(r - pr, .004)*pf;
      vec3 o = (uC*lum*.55 + mix(uP, vec3(1.), .4)*hot*.45)*pk*fade;
      o *= smoothstep(1.600, 1.440, r);
      o = max(o, 0.); if (!(max(o.r, max(o.g, o.b)) >= .002)) discard; gl_FragColor = vec4(o, 1.); }
